package com.infinitylibrary.builder;
import com.infinitylibrary.InfinityLibraryPlugin;import com.infinitylibrary.model.*;import com.infinitylibrary.engine.LayoutPlanner;import com.google.gson.*;import org.bukkit.entity.Player;import java.util.*;import java.util.function.BiConsumer;
/** Server-owned visual drafts. Reads are paged; every mutation checks the draft revision. */
public final class StudioService {
 private static final Gson JSON=new Gson();private final InfinityLibraryPlugin plugin;private final BiConsumer<Player,JsonObject> send;private final Map<UUID,Draft> drafts=new HashMap<>();
 private static final class Model{String token=UUID.randomUUID().toString();Room room;RoomTransform transform;Vector3i offset;Model(Room r,RoomTransform t,Vector3i o){room=r;transform=t;offset=o;}}
 private static final class Draft{Room room;long revision;boolean dirty;String sourceVersion,pairRoom,pairDoor;int pairChoice;Model model,pair;String pairNote="";Deque<Room> undo=new ArrayDeque<>(),redo=new ArrayDeque<>();Draft(Room r,String v){room=r;sourceVersion=v;model=new Model(r,RoomTransform.IDENTITY,new Vector3i(0,0,0));}}
 public StudioService(InfinityLibraryPlugin p,BiConsumer<Player,JsonObject> sender){plugin=p;send=sender;}
 public void cleanup(Player p){drafts.remove(p.getUniqueId());}public void shutdown(){drafts.clear();}
 private String id(JsonObject o,String k){return BuilderProtocol.id(o,k);}private int integer(JsonObject o,String k){double n=o.get(k).getAsDouble();if(!Double.isFinite(n)||n!=Math.rint(n)||Math.abs(n)>100000)throw new IllegalArgumentException("Invalid "+k);return (int)n;}
 private Vector3i vec(JsonObject o,String k){var a=o.getAsJsonArray(k);if(a==null||a.size()!=3)throw new IllegalArgumentException("Three integer coordinates required.");JsonObject v=new JsonObject();v.add("x",a.get(0));v.add("y",a.get(1));v.add("z",a.get(2));return new Vector3i(integer(v,"x"),integer(v,"y"),integer(v,"z"));}
 private JsonArray vector(Vector3i p){JsonArray a=new JsonArray();a.add(p.x());a.add(p.y());a.add(p.z());return a;}
 private JsonObject message(String kind){JsonObject o=new JsonObject();o.addProperty("protocol",1);o.addProperty("kind",kind);return o;}
 public void handle(Player p,String action,JsonObject request){
  if(action.equals("studio_open")){if(drafts.containsKey(p.getUniqueId())&&drafts.get(p.getUniqueId()).dirty&&!request.has("discard"))throw new IllegalArgumentException("Unsaved studio draft. Save it, or confirm Discard and open.");Room r=plugin.getRoomManager().getActive(id(request,"room")).orElseThrow(()->new IllegalArgumentException("Active room not found."));Draft d=new Draft(r,plugin.getBuilderBridge().version(r));drafts.put(p.getUniqueId(),d);header(p,d,"a");return;}
  Draft d=drafts.get(p.getUniqueId());if(d==null)throw new IllegalArgumentException("Open a saved room in Studio first.");
  if(action.equals("studio_sync")){header(p,d,"a");if(d.pair!=null)header(p,d,"b");return;}
  if(action.equals("studio_chunk")){chunk(p,d,request);return;}
  if(request.get("draftRevision").getAsLong()!=d.revision)throw new IllegalArgumentException("Studio draft changed. Sync before editing again.");
  switch(action){
   case "studio_area"->{RoomEditor.Area a=new RoomEditor.Area(id(request,"areaKind"),id(request,"id"),vec(request,"min"),vec(request,"size"),request.get("category").getAsString(),request.get("direction").getAsString(),integer(request,"floor"),request.get("fill").getAsString(),request.get("gap").getAsDouble(),request.get("rotate").getAsBoolean(),request.get("stack").getAsBoolean(),request.get("weight").getAsDouble());mutate(d,RoomEditor.area(d.room,a,request.get("previous").getAsString(),request.has("delete")&&request.get("delete").getAsBoolean()));refresh(p,d);}
   case "studio_paint"->{String block=request.get("block").getAsString();if(block.length()>1024)throw new IllegalArgumentException("Block state too long.");var data=org.bukkit.Bukkit.createBlockData(block);mutate(d,RoomEditor.paint(d.room,vec(request,"min"),vec(request,"size"),data.getAsString()));refresh(p,d);}
   case "studio_undo","studio_redo"->{var source=action.endsWith("redo")?d.redo:d.undo;var target=action.endsWith("redo")?d.undo:d.redo;if(source.isEmpty())throw new IllegalArgumentException("No studio history in that direction.");target.push(d.room);d.room=source.pop();updated(d);refresh(p,d);}
   case "studio_save"->{String name=id(request,"room");var old=plugin.getRoomManager().getActive(name);String expected=request.has("expected")?request.get("expected").getAsString():"";if(old.isPresent()&&!plugin.getBuilderBridge().version(old.get()).equals(expected))throw new IllegalArgumentException("Saved template changed or replacement was not confirmed. Select its current version before replacing.");Room result=RoomEditor.rename(d.room,name,RoomType.parse(request.get("type").getAsString()));plugin.getRoomManager().saveVisualTemplate(result);d.room=result;d.sourceVersion=plugin.getBuilderBridge().version(result);d.dirty=false;d.undo.clear();d.redo.clear();d.revision++;d.model=new Model(result,RoomTransform.IDENTITY,new Vector3i(0,0,0));d.pair=null;header(p,d,"a");}
   case "studio_pair"->pair(p,d,request);
   default->throw new IllegalArgumentException("Unknown studio action.");
  }
 }
 private void mutate(Draft d,Room room){d.undo.push(d.room);while(d.undo.size()>8)d.undo.removeLast();d.redo.clear();d.room=room;updated(d);}
 private void updated(Draft d){d.revision++;d.dirty=true;d.model=new Model(d.room,RoomTransform.IDENTITY,new Vector3i(0,0,0));d.pair=null;d.pairNote="Room changed; rebuild adjacent preview.";}
 private void refresh(Player p,Draft d){if(d.pairRoom!=null){try{JsonObject o=new JsonObject();o.addProperty("room",d.pairRoom);o.addProperty("door",d.pairDoor);o.addProperty("choice",d.pairChoice);pair(p,d,o);return;}catch(IllegalArgumentException ex){d.pair=null;d.pairNote="Adjacent preview: "+ex.getMessage();}}header(p,d,"a");}
 private void pair(Player p,Draft d,JsonObject request){d.pair=null;Room other=plugin.getRoomManager().getActive(id(request,"room")).orElseThrow(()->new IllegalArgumentException("Adjacent room not found."));String door=request.get("door").getAsString();d.pairRoom=other.id();d.pairDoor=door;d.pairChoice=integer(request,"choice");var target=d.room.connections().stream().filter(c->door.isEmpty()||c.id().equals(door)).findFirst().orElseThrow(()->new IllegalArgumentException("Choose a base-room connection first; variant doors can be inspected using live preview."));List<Model> fits=new ArrayList<>();var aBox=new LayoutPlanner.Box(new Vector3i(0,0,0),d.room.size(),d.room.connections());for(var transform:RoomTransform.all())for(var c:other.connections()){var entrance=c.transform(transform,other.size());if(!target.compatibleWith(entrance))continue;Vector3i offset=target.position().subtract(entrance.position());var doors=other.connections().stream().map(cp->cp.transform(transform,other.size()).offset(cp.id(),offset)).toList();var bBox=new LayoutPlanner.Box(offset,transform.transformedSize(other.size()),doors);if(!aBox.conflicts(bBox))fits.add(new Model(other,transform,offset));}if(fits.isEmpty()){d.pairNote="No compatible non-overlapping base doorway (check size, facing and floor).";header(p,d,"a");return;}int choice=Math.floorMod(integer(request,"choice"),fits.size());d.pair=fits.get(choice);d.pairNote="Connected "+target.id()+" · option "+(choice+1)+"/"+fits.size()+" · shared doorway plane";header(p,d,"a");header(p,d,"b");}
 private void header(Player p,Draft d,String slot){Model m=slot.equals("a")?d.model:d.pair;if(m==null)return;JsonObject o=message("studio_model");o.addProperty("slot",slot);o.addProperty("model",m.token);o.addProperty("room",m.room.id());o.addProperty("type",m.room.type().name());o.addProperty("draftRevision",d.revision);o.addProperty("dirty",d.dirty);o.addProperty("undo",!d.undo.isEmpty());o.addProperty("redo",!d.redo.isEmpty());o.addProperty("version",d.sourceVersion);o.addProperty("pairNote",d.pairNote);o.addProperty("hasPair",d.pair!=null);o.add("size",vector(m.transform.transformedSize(m.room.size())));o.add("offset",vector(m.offset));o.addProperty("total",m.room.blocks().size());o.addProperty("areaTotal",RoomEditor.areas(m.room).size());o.add("areas",areaPage(m,slot,0));send.accept(p,o);}
 private JsonArray areaPage(Model m,String slot,int start){JsonArray areas=new JsonArray();var all=RoomEditor.areas(m.room);for(var a:all.stream().skip(start).limit(12).toList()){JsonObject item=JSON.toJsonTree(a).getAsJsonObject();item.add("min",vector(a.min()));item.add("size",vector(a.size()));if(slot.equals("b")){Vector3i lo=m.transform.transform(a.min(),m.room.size()),hi=m.transform.transform(a.min().add(a.size()).subtract(new Vector3i(1,1,1)),m.room.size());Vector3i min=new Vector3i(Math.min(lo.x(),hi.x()),Math.min(lo.y(),hi.y()),Math.min(lo.z(),hi.z()));item.add("min",vector(min));item.add("size",vector(new Vector3i(Math.abs(lo.x()-hi.x())+1,Math.abs(lo.y()-hi.y())+1,Math.abs(lo.z()-hi.z())+1)));}areas.add(item);}return areas;}
 private void chunk(Player p,Draft d,JsonObject request){String slot=request.get("slot").getAsString();Model m=slot.equals("a")?d.model:d.pair;if(m==null||!m.token.equals(request.get("model").getAsString()))return;int start=integer(request,"from");if(start<0||start>m.room.blocks().size())throw new IllegalArgumentException("Invalid model cursor.");var o=message("studio_blocks");o.addProperty("slot",slot);o.addProperty("model",m.token);o.addProperty("from",start);JsonArray cells=new JsonArray();int length=0,cursor=start;while(cursor<m.room.blocks().size()&&cells.size()<256){RoomBlock b=m.room.blocks().get(cursor);Vector3i at=m.transform.transform(b.position(),m.room.size());JsonArray cell=new JsonArray();cell.add(at.x());cell.add(at.y());cell.add(at.z());cell.add(b.blockData());int bytes=cell.toString().length()*3+2;if(length+bytes>16000&&cells.size()>0)break;cells.add(cell);length+=bytes;cursor++;}o.add("blocks",cells);int areaFrom=request.has("areaFrom")?integer(request,"areaFrom"):0;if(areaFrom<0)throw new IllegalArgumentException("Invalid area cursor.");o.addProperty("areaFrom",areaFrom);o.add("areas",areaPage(m,slot,areaFrom));o.addProperty("next",cursor);send.accept(p,o);}
}
